from dataclasses import dataclass, field
from typing import Optional
from mashumaro import DataClassDictMixin, field_options
from mashumaro.config import BaseConfig
@dataclass
class C(DataClassDictMixin):
    x: int = field(metadata=field_options(alias='xx'))
    class Config(BaseConfig):
        serialize_by_alias = True
        forbid_extra_keys = True
@dataclass
class P(DataClassDictMixin):
    a: int
    c: Optional[C] = field(default=None, metadata=field_options(flatten=True, flatten_prefix=True))
    class Config(BaseConfig): forbid_extra_keys = True
for p in [P(2,C(3)),P(2,None)]:
    d=p.to_dict(); print(d, P.from_dict(d))
